package com.primehr.performancemanagement;
import com.primehr.performancemanagement.domain.*;import org.junit.jupiter.api.Test;import java.time.*;import static org.assertj.core.api.Assertions.*;
class PerformanceAppealInterventionTest{
 @Test void appealPreservesDraftSubmittedAndTerminalBoundaries(){PerformanceRatingAppeal appeal=new PerformanceRatingAppeal("A","final-1","case-1","EMP-1","Incorrect actual","Recalculate");appeal.update("Corrected grounds","Recalculate exact rubric");appeal.submit(Instant.parse("2026-09-25T00:00:00Z"));assertThatThrownBy(()->appeal.update("late","late")).hasMessageContaining("draft");assertThatThrownBy(()->appeal.decide(PerformanceRatingAppeal.Status.MODIFIED,"Accepted",null,"PMT-1",Instant.now())).hasMessageContaining("successor");appeal.decide(PerformanceRatingAppeal.Status.UPHELD,"Evidence supports rating",null,"PMT-1",Instant.now());assertThat(appeal.getStatus()).isEqualTo(PerformanceRatingAppeal.Status.UPHELD);}
 @Test void improvementPlanRequiresReceiptAndControlledLifecycle(){PerformanceIntervention p=new PerformanceIntervention("A","final-1","case-1","rule-1","EMP-1",PerformanceInterventionRule.Action.PIP_REQUIRED);p.issue("Improve timeliness","Weekly coaching","SUP-1",LocalDate.of(2026,10,1),LocalDate.of(2026,12,1),"PMT-1",Instant.now());assertThatThrownBy(()->p.acknowledge("OTHER",null,Instant.now())).hasMessageContaining("subject");p.acknowledge("EMP-1","Received",Instant.now());p.start();p.complete(Instant.now());p.close("Objectives verified",Instant.now());assertThat(p.getStatus()).isEqualTo(PerformanceIntervention.Status.CLOSED);}
 @Test void checkpointSeparatesEmployeeFeedbackFromPrivatePmtNote(){PerformanceInterventionCheckpoint p=new PerformanceInterventionCheckpoint("A","pip-1",LocalDate.of(2026,10,15),"First checkpoint");p.complete("On track","Continue coaching","PMT deliberation","SUP-1",Instant.now());assertThat(p.getEmployeeVisibleFeedback()).isEqualTo("Continue coaching");assertThat(p.getPrivatePmtNote()).isEqualTo("PMT deliberation");p.verify();assertThat(p.getStatus()).isEqualTo(PerformanceInterventionCheckpoint.Status.VERIFIED);}
}
